        )?;
        conn.execute_batch(&schema_sql(config.rank.title_weight))?;
        let tx = conn.transaction()?;
        let mut ingest = Ingest::new(&tx, &mappings, opts, false)?;
        for s in sources {
            ingest.source(s, sql_for(config, s))?;
        }
        let mut report = ingest.finish()?;
